DROP TABLE "検査データ" IF EXISTS;

CREATE TABLE "検査データ" (
  "ID" INTEGER GENERATED BY DEFAULT AS IDENTITY (START WITH 1) NOT NULL PRIMARY KEY,
  "品名" VARCHAR(100) NOT NULL,
  "ロット番号" VARCHAR(100) NOT NULL,
  "状態" VARCHAR(100),
  "日付" DATE NOT NULL,
  "検査日時" TIMESTAMP NOT NULL,
  "NG回数" INTEGER DEFAULT 0 NOT NULL,
  "検査名" VARCHAR(100) NOT NULL,
  "判定結果" VARCHAR(100) NOT NULL,
  "検査項目1" VARCHAR(20),
  "検査項目2" VARCHAR(20),
  "検査項目3" VARCHAR(20),
  "検査項目4" VARCHAR(20),
  "検査項目5" VARCHAR(20),
  "検査項目6" VARCHAR(20),
  "検査項目7" VARCHAR(20),
  "検査項目8" VARCHAR(20),
  "検査項目9" VARCHAR(20),
  "検査項目10" VARCHAR(20),
  "検査員" VARCHAR(100) NOT NULL,
  CONSTRAINT "UQ_検査データ" UNIQUE ("品名", "ロット番号", "検査名", "NG回数")
);
